//! display/dc/dc_dsc.h + dsc/dcn20/dcn20_dsc.{h,c} (Linux 6.18.55), with the
//! `dsc_regs`/`dsc_shift`/`dsc_mask` table of dcn21_resource.c: the display
//! stream compressor (DSC) of Renoir's resource pool. Renoir reuses the dcn20
//! DSC; the pool creates `res_cap_rn.num_dsc` (3) of them.
//!
//! `dcn21_dsc_create` → `dsc2_construct` stores the instance, funcs and
//! register pointers and the max image width. The ops of dcn20_dsc.c are
//! ported as the hw sequencer reaches them. The register tables are machine-generated by
//! `dcgen.py` from `DSC_REG_LIST_DCN20` / `DSC_REG_LIST_SH_MASK_DCN20`.
#![allow(dead_code)]

use crate::amdgpu_device::amdgpu_device;
use crate::dc_helper::{reg_get, reg_get_n};
use crate::regs::*;
use alloc::boxed::Box;

/// Which `dsc_funcs` vtable the base points at (dcn20_dsc.c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum dsc_funcs {
    dcn20_dsc_funcs,
}

/// `struct dsc_funcs` (dsc.h), the members ported.
#[derive(Default, Clone, Copy)]
pub struct dsc_ops {
    pub dsc_read_state: Option<fn(&amdgpu_device, &dcn20_dsc, &mut dcn_dsc_state)>,
}

/// `dcn20_dsc_funcs` (dcn20_dsc.c), as far as ported.
const DCN20_DSC_FUNCS: dsc_ops = dsc_ops {
    dsc_read_state: Some(dsc2_read_state),
};

impl dsc_funcs {
    pub fn ops(self) -> &'static dsc_ops {
        match self {
            dsc_funcs::dcn20_dsc_funcs => &DCN20_DSC_FUNCS,
        }
    }
}

/// `struct dcn_dsc_state` (dsc.h).
#[derive(Default, Clone, Copy, Debug)]
pub struct dcn_dsc_state {
    pub dsc_clock_en: u32,
    pub dsc_slice_width: u32,
    pub dsc_bits_per_pixel: u32,
    pub dsc_slice_height: u32,
    pub dsc_pic_width: u32,
    pub dsc_pic_height: u32,
    pub dsc_slice_bpg_offset: u32,
    pub dsc_chunk_size: u32,
    pub dsc_fw_en: u32,
    pub dsc_opp_source: u32,
}

/// `struct display_stream_compressor` (dc_dsc.h): the base object. Linux' `ctx`
/// is not stored (see `clock_source`).
#[derive(Default)]
pub struct display_stream_compressor {
    pub funcs: Option<dsc_funcs>,
    pub inst: u32,
}

/// `struct dcn20_dsc` (dcn20_dsc.h): the concrete DSC. `reg_vals` (the decoded
/// register values) joins with a DSC programming op grow-as-reached.
#[derive(Default)]
pub struct dcn20_dsc {
    pub base: display_stream_compressor,
    pub dsc_regs: Option<&'static dcn20_dsc_registers>,
    pub dsc_shift: Option<&'static dcn20_dsc_shift>,
    pub dsc_mask: Option<&'static dcn20_dsc_mask>,
    pub max_image_width: i32,
}

impl dcn20_dsc {
    /// `dsc->funcs`.
    pub fn funcs(&self) -> &'static dsc_ops {
        self.base.funcs.expect("dsc funcs").ops()
    }

    fn rsm(&self) -> (&'static dcn20_dsc_registers, &'static dcn20_dsc_shift, &'static dcn20_dsc_mask) {
        (self.dsc_regs.unwrap(), self.dsc_shift.unwrap(), self.dsc_mask.unwrap())
    }
}

/// `dsc2_read_state` (dcn20_dsc.c).
pub fn dsc2_read_state(adev: &amdgpu_device, dsc20: &dcn20_dsc, s: &mut dcn_dsc_state) {
    let c = dsc20.rsm();
    s.dsc_clock_en = reg_get!(adev, c, DSC_TOP_CONTROL, DSC_CLOCK_EN);
    s.dsc_slice_width = reg_get!(adev, c, DSCC_PPS_CONFIG3, SLICE_WIDTH);
    s.dsc_bits_per_pixel = reg_get!(adev, c, DSCC_PPS_CONFIG1, BITS_PER_PIXEL);
    s.dsc_slice_height = reg_get!(adev, c, DSCC_PPS_CONFIG3, SLICE_HEIGHT);
    s.dsc_chunk_size = reg_get!(adev, c, DSCC_PPS_CONFIG1, CHUNK_SIZE);
    s.dsc_pic_width = reg_get!(adev, c, DSCC_PPS_CONFIG2, PIC_WIDTH);
    s.dsc_pic_height = reg_get!(adev, c, DSCC_PPS_CONFIG2, PIC_HEIGHT);
    s.dsc_slice_bpg_offset = reg_get!(adev, c, DSCC_PPS_CONFIG7, SLICE_BPG_OFFSET);
    let [fw_en, opp_source] =
        reg_get_n!(adev, c, DSCRM_DSC_FORWARD_CONFIG, DSCRM_DSC_FORWARD_EN, DSCRM_DSC_OPP_PIPE_SOURCE);
    s.dsc_fw_en = fw_en;
    s.dsc_opp_source = opp_source;
}

/// `dsc2_construct` (dcn20_dsc.c): store the instance, funcs and registers.
pub fn dsc2_construct(
    dsc: &mut dcn20_dsc,
    inst: u32,
    dsc_regs: &'static dcn20_dsc_registers,
    dsc_shift: &'static dcn20_dsc_shift,
    dsc_mask: &'static dcn20_dsc_mask,
) {
    dsc.base.inst = inst;
    dsc.base.funcs = Some(dsc_funcs::dcn20_dsc_funcs);
    dsc.dsc_regs = Some(dsc_regs);
    dsc.dsc_shift = Some(dsc_shift);
    dsc.dsc_mask = Some(dsc_mask);
    dsc.max_image_width = 5184;
}

/// `dcn21_dsc_create` (dcn21_resource.c): allocate a `dcn20_dsc` for `inst` and
/// construct it.
pub fn dcn21_dsc_create(inst: u32) -> Box<dcn20_dsc> {
    let mut dsc = Box::new(dcn20_dsc::default());
    dsc2_construct(&mut dsc, inst, &DSC_REGS[inst as usize], &DSC_SHIFT, &DSC_MASK);
    dsc
}

